/* kck_work_ui 0.3.1 - generated by build.py, do not edit by hand */
/* kck_work_ui: mode (Auto / Light / Dark) and colour theme (palette), one storage key each for every app.
   Load in <head> without defer so the saved choices are applied before first paint.

   Mode:     <button data-kck-theme="auto|light|dark">  or  <button data-kck-theme-cycle>
   Palette:  <div data-kck-palettes></div>  is filled with a swatch picker
   Default:  <html data-palette-default="teal">  sets the palette until the user picks one on this device
   Account:  listen for "kck:change" (detail: {mode, palette, source}) to save a pick to the user's profile,
             and call KCK.setPalette(id, {save:false}) when the server tells you the saved one. */
(function () {
  var CFG = {"default": "blue", "palettes": [{"id": "blue", "label": "Blue", "light": "#1f5fbf", "dark": "#2563eb"}, {"id": "teal", "label": "Teal", "light": "#0f766e", "dark": "#14b8a6"}, {"id": "green", "label": "Green", "light": "#15803d", "dark": "#22c55e"}, {"id": "amber", "label": "Amber", "light": "#e8a33d", "dark": "#e8a33d"}, {"id": "violet", "label": "Violet", "light": "#6d4fd1", "dark": "#7c3aed"}, {"id": "graphite", "label": "Graphite", "light": "#374151", "dark": "#e5e7eb"}]} || { default: "blue", palettes: [] };
  var MODE_KEY = "kck-theme", PAL_KEY = "kck-palette";
  var LEGACY = ["theme", "vc-theme", "dc-theme", "winget-theme"], root = document.documentElement;

  function get(k) { try { return localStorage.getItem(k); } catch (e) { return null; } }
  function put(k, v) { try { if (v == null) localStorage.removeItem(k); else localStorage.setItem(k, v); } catch (e) {} }
  function known(id) { for (var i = 0; i < CFG.palettes.length; i++) if (CFG.palettes[i].id === id) return true; return false; }

  function dropLegacy() { for (var i = 0; i < LEGACY.length; i++) put(LEGACY[i], null); }

  var mq = window.matchMedia ? window.matchMedia("(prefers-color-scheme: dark)") : null;
  function osDark() { return !!(mq && mq.matches); }

  function mode() {
    var v = get(MODE_KEY);
    if (v) return v;
    for (var i = 0; i < LEGACY.length; i++) {            // adopt an app's old choice once, then forget the old key
      var o = get(LEGACY[i]);
      if (o === "light" || o === "dark") { dropLegacy(); put(MODE_KEY, o); return o; }
    }
    return "auto";
  }
  function palette() {
    var v = get(PAL_KEY);
    if (v && known(v)) return v;
    var d = root.getAttribute("data-palette-default");
    return d && known(d) ? d : CFG.default;
  }

  function paint() {
    var m = mode(), p = palette(), i;
    // data-theme is always an explicit light or dark (Auto is resolved from the OS), so an app's older
    // [data-theme="dark"] rules keep working. data-mode records what the user actually chose.
    root.setAttribute("data-theme", m === "auto" ? (osDark() ? "dark" : "light") : m);
    root.setAttribute("data-mode", m);
    root.setAttribute("data-palette", p);
    var b = document.querySelectorAll("[data-kck-theme]");
    for (i = 0; i < b.length; i++) b[i].setAttribute("aria-pressed", String(b[i].getAttribute("data-kck-theme") === m));
    var c = document.querySelectorAll("[data-kck-theme-cycle]");
    for (i = 0; i < c.length; i++) c[i].textContent = "Theme: " + m.charAt(0).toUpperCase() + m.slice(1);
    var d = document.querySelectorAll("[data-kck-palette]");
    for (i = 0; i < d.length; i++) d[i].setAttribute("aria-pressed", String(d[i].getAttribute("data-kck-palette") === p));
  }
  function notify(source) {
    try { document.dispatchEvent(new CustomEvent("kck:change", { detail: { mode: mode(), palette: palette(), source: source } })); } catch (e) {}
  }
  function setMode(m, o) {
    dropLegacy(); put(MODE_KEY, m === "auto" ? null : m); paint();
    if (!o || o.save !== false) notify("mode");
  }
  function setPalette(id, o) {
    if (!known(id)) return;
    put(PAL_KEY, id); paint();
    if (!o || o.save !== false) notify("palette");
  }

  function buildPickers() {
    var hosts = document.querySelectorAll("[data-kck-palettes]");
    for (var i = 0; i < hosts.length; i++) {
      if (hosts[i].getAttribute("data-built")) continue;
      hosts[i].setAttribute("data-built", "1");
      hosts[i].className = (hosts[i].className + " pal").trim();
      hosts[i].setAttribute("role", "group");
      hosts[i].setAttribute("aria-label", "Colour theme");
      hosts[i].innerHTML = CFG.palettes.map(function (p) {
        return '<button type="button" class="pal__dot" data-kck-palette="' + p.id + '" aria-pressed="false" title="' + p.label +
               '" aria-label="' + p.label + '" style="--dot:' + p.light + ';--dot-d:' + p.dark + '"></button>';
      }).join("");
    }
  }

  if (mq && mq.addEventListener) mq.addEventListener("change", function () { if (mode() === "auto") paint(); });

  window.KCK = { mode: mode, palette: palette, palettes: CFG.palettes, setMode: setMode, setTheme: setMode, setPalette: setPalette };
  paint();
  document.addEventListener("DOMContentLoaded", function () {
    buildPickers(); paint();
    document.addEventListener("click", function (e) {
      var t = e.target.closest && e.target.closest("[data-kck-theme],[data-kck-theme-cycle],[data-kck-palette]");
      if (!t) return;
      if (t.hasAttribute("data-kck-palette")) setPalette(t.getAttribute("data-kck-palette"));
      else if (t.hasAttribute("data-kck-theme-cycle")) { var M = ["auto", "light", "dark"]; setMode(M[(M.indexOf(mode()) + 1) % 3]); }
      else setMode(t.getAttribute("data-kck-theme"));
    });
  });
})();
